static void correct_endian_ret_submit(struct usbip_header_ret_submit *pdu, /* <=== correct_endian_ret_submit */ 
				      int send)
{
	if (send) {
		cpu_to_be32s(&pdu->status);
		cpu_to_be32s(&pdu->actual_length);
		cpu_to_be32s(&pdu->start_frame);
